"use client";
import React, { useState, useEffect } from "react";
import { Ruler, ArrowRight, Shirt, Footprints, Zap, Info, Maximize2 } from "lucide-react";
import { sizeData } from "@/data/sizes";

export default function SizeGuidePage() {
  const [activeCat, setActiveCat] = useState<keyof typeof sizeData>("footwear");
  const [baseUnit, setBaseUnit] = useState<string>("");
  const [targetUnit, setTargetUnit] = useState<string>("");

  useEffect(() => {
    const availableUnits = sizeData[activeCat].units;
    setBaseUnit(availableUnits[0]);
    setTargetUnit(availableUnits[availableUnits.length - 1]);
  }, [activeCat]);

  const categories = [
    { id: "footwear", label: "Footwear", icon: <Footprints size={18} /> },
    { id: "apparel", label: "Apparel", icon: <Shirt size={18} /> },
    { id: "crocs", label: "Crocs", icon: <Zap size={18} /> },
  ];

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 selection:bg-brand selection:text-white overflow-x-hidden">
      
      {/* 1. KINETIC HEADER (Spatial Design) */}
      <header className="relative pt-20 pb-16 px-6 max-w-7xl mx-auto border-b border-foreground/5">
        <div className="absolute top-10 right-10 opacity-5 hidden lg:block">
          <Maximize2 size={300} strokeWidth={0.5} />
        </div>
        
        <div className="relative z-10 space-y-6">
          <div className="flex items-center gap-4">
            <span className="h-px w-16 bg-foreground" />
            <span className="text-[10px] font-black uppercase tracking-[0.8em] animate-pulse">Neural Fit System v2.6</span>
          </div>
          <h1 className="text-[12vw] md:text-[10vw] font-black uppercase italic tracking-tighter leading-[0.75] mix-blend-difference">
            Perfect <br /> <span className="text-brand italic">Symmetry.</span>
          </h1>
        </div>
      </header>

      {/* 2. CATEGORY NAV (Cyber-Segmented Control) */}
      <section className="px-6 -mt-8 relative z-20">
        <div className="max-w-2xl mx-auto flex p-1 bg-foreground text-background rounded-full shadow-[0_20px_50px_rgba(0,0,0,0.2)]">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCat(cat.id as any)}
              className={`flex-1 flex items-center justify-center gap-2 py-4 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-700 ${
                activeCat === cat.id 
                  ? "bg-brand text-foreground" 
                  : "hover:bg-background/10"
              }`}
            >
              {cat.icon} <span className="hidden md:inline">{cat.label}</span>
            </button>
          ))}
        </div>
      </section>

      <main className="max-w-6xl mx-auto px-6 mt-24">
        {/* 3. NEURAL SELECTOR GRID */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 mb-20">
          <div className="lg:col-span-4 space-y-8">
            <div className="space-y-4">
              <h3 className="text-[11px] font-black uppercase tracking-widest opacity-40">Source Input</h3>
              <div className="flex flex-wrap gap-2">
                {sizeData[activeCat].units.map((u: string) => (
                  <button
                    key={u}
                    onClick={() => setBaseUnit(u)}
                    className={`px-6 py-3 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${
                      baseUnit === u ? "bg-foreground text-background border-foreground scale-110" : "border-border opacity-40 hover:opacity-100"
                    }`}
                  >
                    {u}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-[11px] font-black uppercase tracking-widest opacity-40">Target Output</h3>
              <div className="flex flex-wrap gap-2">
                {sizeData[activeCat].units.map((u: string) => (
                  <button
                    key={u}
                    onClick={() => setTargetUnit(u)}
                    className={`px-6 py-3 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${
                      targetUnit === u ? "bg-brand text-foreground border-brand scale-110" : "border-border opacity-40 hover:opacity-100"
                    }`}
                  >
                    {u}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* 4. THE CORE ARCHIVE ENGINE */}
          <div className="lg:col-span-8">
            <div className="bg-muted/10 rounded-4xl border border-foreground/5 overflow-hidden">
              <div className="grid grid-cols-2 border-b border-foreground/5 bg-foreground/5">
                <div className="py-6 px-10 text-[10px] font-black uppercase tracking-widest opacity-30 italic">{baseUnit}</div>
                <div className="py-6 px-10 text-[10px] font-black uppercase tracking-widest opacity-30 italic text-right">{targetUnit}</div>
              </div>

              <div className="divide-y divide-foreground/5">
                {sizeData[activeCat].chart.map((row: any, i: number) => (
                  <div key={i} className="grid grid-cols-2 group hover:bg-brand transition-all duration-500 cursor-crosshair">
                    <div className="py-10 px-10 text-4xl md:text-6xl font-black italic tracking-tighter transition-transform group-hover:translate-x-4">
                      {String(row[baseUnit])}
                    </div>
                    <div className="py-10 px-10 text-4xl md:text-6xl font-black italic tracking-tighter text-right text-foreground/20 group-hover:text-foreground transition-all group-hover:-translate-x-4">
                      {String(row[targetUnit])}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* 5. DYNAMIC MEASUREMENT INTEL */}
        <div className="relative group overflow-hidden rounded-4xl bg-foreground text-background p-12 md:p-20">
          <div className="absolute -right-20 -bottom-20 opacity-10 group-hover:rotate-12 transition-transform duration-1000">
            <Ruler size={400} />
          </div>
          
          <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
            <div className="space-y-6">
              <div className="h-12 w-12 rounded-full border border-background/20 flex items-center justify-center">
                <Info size={20} />
              </div>
              <h2 className="text-4xl font-black uppercase italic leading-none">Measurement <br /> Protocol.</h2>
              <p className="text-sm font-medium opacity-60 leading-relaxed italic uppercase tracking-tighter">
                Our archive is built on ISO standard 19407. Note that anatomical variations may require a ±0.5 scale adjustment. Always measure mid-day for peak accuracy.
              </p>
            </div>

            <div className="space-y-4 border-l border-background/10 pl-0 md:pl-12">
               <div className="space-y-1">
                 <p className="text-[10px] font-black uppercase opacity-40">Engineering Status</p>
                 <p className="text-xl font-bold italic uppercase tracking-widest">Verified 2026</p>
               </div>
               <div className="space-y-1">
                 <p className="text-[10px] font-black uppercase opacity-40">Standardization</p>
                 <p className="text-xl font-bold italic uppercase tracking-widest">Global ISO/TS</p>
               </div>
               <button className="pt-6 text-brand font-black uppercase tracking-widest text-[10px] flex items-center gap-2 hover:gap-4 transition-all">
                 Download Full PDF Specs <ArrowRight size={14} />
               </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}